// Dapatkan akses ke 'flow context' (Kotak Tunggu/Buffer)
let dataStore = flow.get('sheet_data_buffer') || {};

// Ambil bagian topik terakhir (misal: 'voltage', 'Windspeed', 'ML_Status', dll.)
let topicPart = msg.topic.split('/').pop();

// --- Daftar Topik yang Ditunggu (PZEM + Kecepatan Angin + ML Status) ---
const availableTopics = ['voltage', 'current', 'power', 'energy', 'Windspeed', 'windspeedstation', 'winddirdeg', 'humidity', 'temperature', 'noise', 'rainfall', 'ML_Status'];
const requiredTopics = ['Windspeed', 'windspeedstation', 'winddirdeg', 'humidity', 'temperature', 'noise', 'rainfall'];

// 1. Simpan data yang baru datang ke Kotak Tunggu
// Hanya simpan jika topik yang datang adalah salah satu yang dibutuhkan
if (availableTopics.includes(topicPart)) {
  // Jika topiknya ML_Status, simpan sebagai string (jaga-jaga output berupa teks klasifikasi)
  // Selain itu, jadikan Float (angka)
  if (topicPart === 'ML_Status') {
    dataStore[topicPart] = msg.payload.toString();
  } else {
    dataStore[topicPart] = parseFloat(msg.payload);
  }

  // Simpan kembali ke flow context
  flow.set('sheet_data_buffer', dataStore);
} else {
  // Jika topik tidak dikenal, abaikan saja
  return null;
}

// 2. Periksa apakah SELURUH data 'required' sudah lengkap terkumpul di dataStore
const isComplete = requiredTopics.every(topic => dataStore[topic] !== undefined);

if (isComplete) {
  // A. Ambil nilai dari Kotak Tunggu (opsional set ke "OFF" jika kosong)
  const voltage = (dataStore.voltage !== undefined) ? dataStore.voltage : "OFF";
  const current = (dataStore.current !== undefined) ? dataStore.current : "OFF";
  const power = (dataStore.power !== undefined) ? dataStore.power : "OFF";
  const energy = (dataStore.energy !== undefined) ? dataStore.energy : "OFF";
  const mlStatus = (dataStore.ML_Status !== undefined) ? dataStore.ML_Status : "OFF";

  // Data wajib (required)
  const windspeed = dataStore.Windspeed;
  const windspeedstation = dataStore.windspeedstation;
  const winddirdeg = dataStore.winddirdeg;
  const humidity = dataStore.humidity;
  const temperature = dataStore.temperature;
  const noise = dataStore.noise;
  const rainfall = dataStore.rainfall;

  // B. Buat Timestamp (Waktu saat ini)
  const timestamp = new Date().toLocaleString('id-ID', {
    year: 'numeric',
    month: 'numeric',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
    timeZone: 'Asia/Jakarta'
  });

  // C. Format Data (Mengatur jumlah angka di belakang koma)
  let formattedVoltage = (dataStore.voltage !== undefined) ? voltage.toFixed(2) : voltage;
  let formattedCurrent = (dataStore.current !== undefined) ? current.toFixed(2) : current;
  let formattedPower = (dataStore.power !== undefined) ? power.toFixed(1) : power;
  let formattedEnergy = (dataStore.energy !== undefined) ? energy.toFixed(0) : energy;

  // Status tidak perlu toFixed karena bukan angka desimal
  let formattedMLStatus = mlStatus;
  let formattedWindspeed = windspeed.toFixed(2);
  let formattedWindspeedstation = windspeedstation.toFixed(2);
  let formattedWinddirdeg = winddirdeg.toFixed(0);
  let formattedHumidity = humidity.toFixed(2);
  let formattedTemperature = temperature.toFixed(1);
  let formattedNoise = noise.toFixed(1);
  let formattedRainfall = rainfall.toFixed(1);

  // D. Buat Array Baris Baru (Ini akan jadi urutan kolom di Google Sheet)
  const newRow = [
    timestamp, // Kolom A (Waktu)
    formattedVoltage, // Kolom B (Tegangan)
    formattedCurrent, // Kolom C (Arus)
    formattedPower, // Kolom D (Daya)
    formattedEnergy, // Kolom E (Energi)
    formattedWindspeed, // Kolom F (Kecepatan Angin PZEM)
    formattedWindspeedstation, // Kolom G (Kecepatan Angin Station)
    formattedWinddirdeg, // Kolom H (Arah Angin)
    formattedHumidity, // Kolom I (Kelembapan)
    formattedTemperature, // Kolom J (Suhu)
    formattedNoise, // Kolom K (Noise)
    formattedRainfall, // Kolom L (Curah Hujan)
    formattedMLStatus // Kolom M (Status ML)
  ];

  // E. Final Payload untuk Node Google Sheet (Array di dalam Array)
  msg.payload = [newRow];

  // --- Bagian Pembersihan ---
  // Bersihkan Kotak Tunggu agar siap menerima set data baru
  flow.set('sheet_data_buffer', {});

  // Kirim pesan ke Node Google Sheets
  return msg;
}

// Jika data required belum lengkap, jangan kirim apa-apa ke sheet dulu
