return null;

// Input dari GSheet berupa Array of Arrays
let rows = msg.payload;

// Validasi Data
if (!rows || rows.length < 2) return null;

// Fungsi Helper: Parsing Tanggal Indonesia (DD/MM/YYYY, HH.mm.ss)
function parseDateID(dateStr) {
    if (!dateStr) return 0;
    let d = new Date(dateStr);
    if (!isNaN(d.getTime())) return d.getTime();

    try {
        let parts = dateStr.split(/[,\s]+/);
        if (parts.length >= 2) {
            let dParts = parts[0].split('/');
            let tParts = parts[1].split(/[:.]/);

            if (dParts.length === 3) {
                return new Date(dParts[2], dParts[1] - 1, dParts[0], tParts[0] || 0, tParts[1] || 0, tParts[2] || 0).getTime();
            }
        }
    } catch (e) { return 0; }
    return 0;
}

/**
 * Format Data agar seragam menjadi Object
 * Sesuai Urutan GSheet: 
 * A=0(Time), B=1(Volt), C=2(Curr), D=3(Power), E=4(Energy), F=5(Wind Ardu)
 * G=6(Wind Stn), H=7(Dir), I=8(Hum), J=9(Temp), K=10(Noise), L=11(Rain), M=12(ML Status)
 */
function formatRow(row) {
    return {
        serverTime: row[0],
        voltage: parseFloat(row[1]) || 0,
        current: parseFloat(row[2]) || 0,
        power: parseFloat(row[3]) || 0,
        energy: parseFloat(row[4]) || 0,
        Windspeed: parseFloat(row[5]) || 0,           // Angin Arduino
        windspeedstation: parseFloat(row[6]) || 0,    // Angin Stasiun
        winddirdeg: parseFloat(row[7]) || 0,          // Arah Angin
        humidity: parseFloat(row[8]) || 0,            // Kelembapan
        temperature: parseFloat(row[9]) || 0,         // Suhu
        noise: parseFloat(row[10]) || 0,              // Kebisingan
        rainfall: parseFloat(row[11]) || 0,           // Curah Hujan
        ML_Status: row[12] !== undefined ? row[12].toString() : "OFF" // Status ML
    };
}

let resultData = [];
let reqTopic = msg.topic;

// --- SKENARIO 1: REPLAY (TAMPILAN AWAL DASHBOARD) ---
if (reqTopic === 'replay' || msg.payload === 'connect') {
    // Ambil 50 baris terakhir (data terbaru)
