    });

    // C. Format Data
    let formattedVoltage = (dataStore2.voltage !== undefined) ? voltage.toFixed(2) : voltage;
    let formattedCurrent = (dataStore2.current !== undefined) ? current.toFixed(2) : current;
    let formattedPower = (dataStore2.power !== undefined) ? power.toFixed(1) : power;
    let formattedEnergy = (dataStore2.energy !== undefined) ? energy.toFixed(0) : energy;
    let formattedWindspeed = (dataStore2.Windspeed !== undefined) ? windspeed.toFixed(2) : windspeed;
    let formattedMLStatus = mlStatus; 

    // D. Buat Array Baris Baru (Urutan untuk 7 Kolom)
    const newRow = [
        timestamp,          // Kolom A (Waktu)
