    // Ambil 50 baris terakhir (data terbaru)
    let last50 = rows.slice(-50);
    resultData = last50.map(formatRow);

    // Harus 'history2' agar ditangkap oleh ruangan Turbin 2 di Canvas Dashboard
    msg.topic = "history2";
